package com.procurement.quotationcomparison.entity;import jakarta.persistence.*;import lombok.*;import java.math.BigDecimal;@Entity@Table(name="comparison_scores")@Getter@Setter@NoArgsConstructor@AllArgsConstructor@Builder public class ComparisonScore{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)@Column(name="comparison_score_id")private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="comparison_line_id",nullable=false)private QuotationComparisonLine comparisonLine;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="criteria_id",nullable=false)private ComparisonCriteria criteria;@Column(name="obtained_score",nullable=false,precision=8,scale=2)private BigDecimal obtainedScore;@Column(name="maximum_score",nullable=false,precision=8,scale=2)private BigDecimal maximumScore;@Column(nullable=false,precision=5,scale=2)private BigDecimal weight;@Column(name="weighted_score",nullable=false,precision=8,scale=2)private BigDecimal weightedScore;}
